mapper.update:
UPDATE comment_sentiment
comment_id = #{commentId}, sentiment_score = #{sentimentScore}, sentiment_label = #{sentimentLabel}, positive_words = #{positiveWords}, negative_words = #{negativeWords}, update_time = #{updateTime}
WHERE id = #{id}

mapper.select:
SELECT  FROM comment_sentiment

    AND comment_id = #{commentId}
    AND sentiment_label = #{sentimentLabel}

ORDER BY id DESC

SELECT cs.*, c.content as comment_content, u.name as user_name, co.name as course_name FROM comment_sentiment cs LEFT JOIN comment c ON cs.comment_id = c.id LEFT JOIN user u ON c.user_id = u.id LEFT JOIN course co ON c.course_id = co.id
AND cs.sentiment_label = #{sentimentLabel}
ORDER BY cs.id DESC
